interface WashType { String getName(); int getDurationMinutes(); double getCharge(); }
class QuickWash implements WashType { public String getName(){return "Quick";} public int getDurationMinutes(){return 30;} public double getCharge(){return 20;} }
class NormalWash implements WashType { public String getName(){return "Normal";} public int getDurationMinutes(){return 45;} public double getCharge(){return 30;} }
class HeavyWash implements WashType { public String getName(){return "Heavy";} public int getDurationMinutes(){return 60;} public double getCharge(){return 45;} }
class Student { private final String name; Student(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException();name=n;} String getName(){return name;} }
class WashCycle { private final Student student; private final WashType type; private boolean completed; WashCycle(Student s,WashType t){student=s;type=t;} Student getStudent(){return student;} WashType getType(){return type;} void complete(){completed=true;} }
class WashingMachine { private final String id; private WashCycle current; WashingMachine(String id){if(id==null||id.trim().isEmpty())throw new IllegalArgumentException();this.id=id;} String getId(){return id;} boolean isFree(){return current==null;} String start(Student s,WashType t){if(s==null||t==null)throw new IllegalArgumentException();if(current!=null)return "Machine "+id+" is currently busy.";current=new WashCycle(s,t);return t.getName()+" wash started on "+id+" for "+s.getName()+" ("+t.getDurationMinutes()+" min). Charge: ₹"+String.format("%.2f",t.getCharge());} String complete(){if(current==null)return id+" is already free.";current.complete();current=null;return id+" cycle completed. "+id+" is now free.";}}
public class Main { public static void main(String[] args){Student asha=new Student("Asha"),ravi=new Student("Ravi"),neha=new Student("Neha");WashingMachine m1=new WashingMachine("M1"),m2=new WashingMachine("M2");System.out.println(m1.start(asha,new QuickWash()));System.out.println(m1.start(ravi,new HeavyWash()));System.out.println(m2.start(ravi,new HeavyWash()));System.out.println(m1.complete());System.out.println(m1.start(neha,new NormalWash()));} }